-- Check if all effectivenessrobot values exist in robot_details
SELECT COUNT(*) FROM (
    SELECT DISTINCT ps.effectivenessrobot 
    FROM performance_and_safety ps
) ps_vals
WHERE ps_vals.effectivenessrobot NOT IN (SELECT botdetreg FROM robot_details);

-- Check if all effectivenessrobot values have corresponding operations
SELECT COUNT(*) FROM (
    SELECT DISTINCT ps.effectivenessrobot 
    FROM performance_and_safety ps
) ps_vals
WHERE ps_vals.effectivenessrobot NOT IN (SELECT operbotdetref FROM operation);

-- Check total distinct robots in operation vs performance_and_safety
SELECT COUNT(DISTINCT operbotdetref) FROM operation;
SELECT COUNT(*) FROM performance_and_safety;
